// Sum token usage across every message the agent produced
function langgraphMetrics(result) {
  let input = 0, output = 0, total = 0;
  for (const msg of result.messages ?? []) {
    const u = msg.response_metadata?.token_usage ?? msg.usage_metadata;
    if (!u) continue;
    input  += u.input_tokens  ?? u.prompt_tokens     ?? 0;
    output += u.output_tokens ?? u.completion_tokens  ?? 0;
    total  += u.total_tokens  ?? u.totalTokens        ?? 0;
  }
  return { success: true, usage: { total: total || input + output, input, output } };
}

